-- SYNTHETIC CANDIDATE. Local simulation only; full rebuild, not a production incremental deployment.
CREATE DATABASE IF NOT EXISTS DMA_SIM;
CREATE SCHEMA IF NOT EXISTS DMA_SIM.BRONZE;
CREATE SCHEMA IF NOT EXISTS DMA_SIM.SILVER;
CREATE SCHEMA IF NOT EXISTS DMA_SIM.GOLD;
CREATE TABLE IF NOT EXISTS DMA_SIM.BRONZE.BILLING_INVOICE_CDC (tenant_id VARCHAR, invoice_id VARCHAR, customer_id VARCHAR, issued_at VARCHAR, gross_cents VARCHAR, discount_cents VARCHAR, status VARCHAR, currency VARCHAR, source_seq NUMBER(38,0), op VARCHAR, arrival_seq NUMBER(38,0));
CREATE TABLE IF NOT EXISTS DMA_SIM.BRONZE.BILLING_PAYMENT_CDC (tenant_id VARCHAR, entry_id VARCHAR, invoice_id VARCHAR, amount_cents VARCHAR, status VARCHAR, currency VARCHAR, source_seq NUMBER(38,0), op VARCHAR, arrival_seq NUMBER(38,0));
CREATE TABLE IF NOT EXISTS DMA_SIM.BRONZE.BILLING_CREDIT_CDC (tenant_id VARCHAR, entry_id VARCHAR, invoice_id VARCHAR, amount_cents VARCHAR, status VARCHAR, currency VARCHAR, source_seq NUMBER(38,0), op VARCHAR, arrival_seq NUMBER(38,0));
CREATE TABLE IF NOT EXISTS DMA_SIM.BRONZE.BILLING_CUSTOMER_HISTORY (tenant_id VARCHAR, customer_id VARCHAR, valid_from VARCHAR, valid_to VARCHAR, segment VARCHAR);
